#include <stdio.h>
#include <stdint.h>

/* Sahte donanim: IDR kaydedicisinin 0. biti butonun pini.
   Buton basili = 0 (cekme direnci yukari). */
static volatile uint32_t GPIO_IDR;

/* 5 ms'lik ornekleme adimlariyla okunan ham pin dizisi (1 = bosta, 0 = basili). */
static const uint8_t raw[] = {
    1,1,1, 0,1,0,0, 0,0,0,0, 1,0,1,1, 1,1,1,1,
    0,0,1,0, 0,0,0, 1,1,1,1
};

#define N 3                 /* kabul icin gereken ardisik ayni ornek */

int main(void) {
    uint8_t stable = 1;     /* dogrulanmis durum */
    uint8_t cand  = 1;      /* aday durum */
    uint8_t cnt   = 0;      /* adayin ust uste kac kez goruldugu */
    int presses = 0;

    for (unsigned i = 0; i < sizeof raw; i++) {
        GPIO_IDR = raw[i];                  /* donanimi tazele */
        uint8_t pin = (uint8_t)(GPIO_IDR & 1u);

        if (pin != cand) { cand = pin; cnt = 1; }
        else if (cnt < N) { cnt++; }

        if (cnt >= N && stable != cand) {
            stable = cand;
            if (stable == 0) {              /* dusen kenar = basma */
                presses++;
                printf("basma %d @ t=%u ms\n", presses, i * 5u);
            }
        }
    }
    printf("toplam=%d\n", presses);
    return 0;
}

#include <stdio.h>
#include <stdint.h>
#include <math.h>

/* Sahte ADC: veri kaydedicisine her okumada yeni ham deger yazilir. */
static volatile uint32_t ADC_DR;

#define ADC_MAX   4095.0
#define VREF_MV   3300.0
#define RFIX      10000.0
#define R25       10000.0
#define BETA      3950.0
#define T0K       298.15

static const uint16_t raw[] = { 3157, 2048, 1082, 816 };

int main(void) {
    for (unsigned i = 0; i < sizeof raw / sizeof raw[0]; i++) {
        ADC_DR = raw[i];
        uint32_t code = ADC_DR & 0xFFFu;

        double v_mv = code * VREF_MV / ADC_MAX;          /* kod -> mV */
        double r    = RFIX * v_mv / (VREF_MV - v_mv);    /* bolucuden NTC direnci */
        double tk   = 1.0 / (1.0 / T0K + log(r / R25) / BETA);
        printf("kod=%4u  V=%7.2f mV  R=%8.1f ohm  T=%6.2f C\n",
               code, v_mv, r, tk - 273.15);
    }
    return 0;
}

#include <stdio.h>
#include <stdint.h>

/* Sahte donanim: IDR'nin 0. biti A kanali, 1. biti B kanali. */
static volatile uint32_t GPIO_IDR;

/* Dort evre kod cozme tablosu: indeks = (onceki<<2) | simdiki
   +1 ileri, -1 geri, 0 degisim yok, 2 = gecersiz (atlanan adim) */
static const int8_t lut[16] = {
     0, +1, -1,  2,
    -1,  0,  2, +1,
    +1,  2,  0, -1,
     2, -1, +1,  0
};

/* Olculen AB dizisi (gray: 00,01,11,10). */
static const uint8_t ab[] = {
    0x0, 0x1, 0x3, 0x2, 0x0, 0x1, 0x3,
    0x1, 0x0, 0x2, 0x3,
    0x0
};

int main(void) {
    int32_t pos = 0;
    int errors = 0;
    uint8_t prev = ab[0];

    for (unsigned i = 1; i < sizeof ab; i++) {
        GPIO_IDR = ab[i];
        uint8_t cur = (uint8_t)(GPIO_IDR & 3u);
        int8_t d = lut[(prev << 2) | cur];
        if (d == 2) { errors++; }
        else { pos += d; }
        prev = cur;
    }
    printf("pos=%ld hata=%d\n", (long)pos, errors);

    /* 500 PPR enkoder, dort evre -> 2000 say/devir; 100 ms'de 3400 say */
    long counts = 3400, cpr = 4 * 500;
    double rpm = (double)counts / cpr / 0.100 * 60.0;
    printf("rpm=%.1f\n", rpm);
    return 0;
}

#include <stdio.h>
#include <stdint.h>

/* Sahte UART: durum kaydedicisinin 0. biti "veri hazir", veri kaydedicisi bayti verir. */
static volatile uint32_t UART_SR;
static volatile uint32_t UART_DR;

/* Hatta gelen bayt akisi: uc cerceve.
   Cerceve bicimi: 0xAA | uzunluk | veri[uzunluk] | saglama
   saglama = (uzunluk + veri baytlarinin toplami) & 0xFF  */
static const uint8_t stream[] = {
    0xAA, 0x04, 0x10, 0x20, 0x30, 0x40, 0xA4,
    0xAA, 0x03, 0x01, 0x02, 0x84, 0x8B,
    0xAA, 0x02, 0x7F, 0x01, 0x82
};

int main(void) {
    unsigned i = 0;
    int ok = 0, bad = 0;

    while (i < sizeof stream) {
        UART_SR = 1u;                 /* veri hazir */
        UART_DR = stream[i++];
        if ((UART_SR & 1u) == 0 || (UART_DR & 0xFFu) != 0xAA) continue;  /* bas baytini ara */

        uint8_t len = stream[i++];
        uint8_t sum = len;
        printf("cerceve: uzunluk=%u veri=", len);
        for (uint8_t k = 0; k < len; k++) {
            uint8_t b = stream[i++];
            sum = (uint8_t)(sum + b);
            printf("%02X ", b);
        }
        uint8_t chk = stream[i++];
        if (chk == sum) { ok++;  printf("-> SAGLAMA TAMAM (%02X)\n", chk); }
        else            { bad++; printf("-> HATA: gelen %02X, hesaplanan %02X\n", chk, sum); }
    }
    printf("tamam=%d hatali=%d\n", ok, bad);
    return 0;
}

#include <stdio.h>
#include <stdint.h>

/* Sahte ADC kaydedicisi */
static volatile uint32_t ADC_DR;

#define N 8                      /* hareketli ortalama penceresi */

/* Gurultulu olcumler: 2048 civari, 7. ornekte tek ornekli sicrama (aykiri deger) */
static const uint16_t raw[] = {
    2048, 2052, 2045, 2050, 2047, 2051, 2049, 3500,
    2048, 2046, 2050, 2049, 2047, 2052, 2048, 2050
};

static uint16_t med3(uint16_t a, uint16_t b, uint16_t c) {
    if (a > b) { uint16_t t = a; a = b; b = t; }
    if (b > c) { uint16_t t = b; b = c; c = t; }
    if (a > b) { uint16_t t = a; a = b; b = t; }
    return b;
}

int main(void) {
    uint16_t buf[N] = {0};
    uint32_t sum = 0;
    unsigned idx = 0, filled = 0;
    uint16_t m1 = raw[0], m2 = raw[0];

    for (unsigned i = 0; i < sizeof raw / sizeof raw[0]; i++) {
        ADC_DR = raw[i];
        uint16_t x = (uint16_t)(ADC_DR & 0xFFFFu);

        /* 3 noktali ortanca: aykiri degeri eler */
        uint16_t med = med3(m2, m1, x);
        m2 = m1; m1 = x;

        /* hareketli ortalama: dairesel tampon, tamsayi aritmetigi */
        sum -= buf[idx];
        buf[idx] = x;
        sum += x;
        idx = (idx + 1) % N;
        if (filled < N) filled++;
        uint16_t avg = (uint16_t)((sum + filled / 2) / filled);

        if (i >= 6 && i <= 9)
            printf("i=%2u ham=%4u ortanca=%4u ortalama=%4u\n", i, x, med, avg);
    }
    printf("son ortalama=%u\n", (unsigned)((sum + N / 2) / N));
    return 0;
}

#include <stdio.h>
#include <stdint.h>

/* Sahte Flash: okuma penceresi kaydedicisi (her erisimde taze veri) */
static volatile uint32_t FLASH_DR;

#define REC 5            /* kayit: sira(2) + deger(2) + CRC8(1) */
#define NREC 6

/* Dairesel gunluk alani: silinmis bayt = 0xFF.
   Son kayit yazilirken enerji kesilmis (yarim yazma). */
static const uint8_t log_area[NREC][REC] = {
    {0x00, 0x05, 0x00, 0x08, 0xF8},   /* sira=5  deger=8   */
    {0x00, 0x06, 0x00, 0x09, 0x42},   /* sira=6  deger=9   */
    {0x00, 0x07, 0x00, 0x0A, 0x20},   /* sira=7  deger=10  */
    {0x00, 0x08, 0x00, 0x0B, 0xFF},   /* sira=8: CRC yazilamadi (yarim yazma) */
    {0xFF, 0xFF, 0xFF, 0xFF, 0xFF},   /* silinmis */
    {0xFF, 0xFF, 0xFF, 0xFF, 0xFF}
};

static uint8_t crc8(const uint8_t *p, unsigned n) {
    uint8_t c = 0x00;
    for (unsigned i = 0; i < n; i++) {
        c ^= p[i];
        for (int b = 0; b < 8; b++)
            c = (uint8_t)((c & 0x80) ? ((c << 1) ^ 0x07) : (c << 1));
    }
    return c;
}

int main(void) {
    int best = -1; unsigned bestseq = 0; int bad = 0, erased = 0;

    for (unsigned r = 0; r < NREC; r++) {
        uint8_t buf[REC];
        int all_ff = 1;
        for (unsigned k = 0; k < REC; k++) {
            FLASH_DR = log_area[r][k];
            buf[k] = (uint8_t)(FLASH_DR & 0xFFu);
            if (buf[k] != 0xFF) all_ff = 0;
        }
        if (all_ff) { erased++; continue; }

        uint8_t c = crc8(buf, REC - 1);
        unsigned seq = (unsigned)(buf[0] << 8 | buf[1]);
        if (c != buf[REC - 1]) {
            bad++;
            printf("kayit %u: sira=%u CRC hatali (hesap=%02X, kayitli=%02X)\n",
                   r, seq, c, buf[REC - 1]);
            continue;
        }
        printf("kayit %u: sira=%u deger=%u gecerli\n", r, seq,
               (unsigned)(buf[2] << 8 | buf[3]));
        if (seq >= bestseq) { bestseq = seq; best = (int)r; }
    }
    printf("son gecerli kayit=%d (sira=%u), bozuk=%d, silinmis=%d\n",
           best, bestseq, bad, erased);
    printf("sonraki yazma konumu=%d\n", best + 1 + bad);
    return 0;
}

#include <stdio.h>
#include <stdint.h>

/* Sahte donanim: 16 bitlik serbest calisan sayac (1 us adim) ve isaret pini */
static volatile uint32_t TIM_CNT;
static volatile uint32_t GPIO_ODR;

/* Olcum: baslangic ve bitis sayac degerleri. Ikinci cift sayacin tasma
   sinirini geciyor (0xFFF0 -> 0x0020). */
static const uint16_t t0[] = { 0x1000, 0xFFF0 };
static const uint16_t t1[] = { 0x1050, 0x0020 };

int main(void) {
    for (unsigned i = 0; i < 2; i++) {
        TIM_CNT = t0[i];
        uint16_t a = (uint16_t)TIM_CNT;
        GPIO_ODR |= 1u;                 /* isaret pini yukari */

        TIM_CNT = t1[i];
        uint16_t b = (uint16_t)TIM_CNT;
        GPIO_ODR &= ~1u;                /* isaret pini asagi */

        int   yanlis = (int)b - (int)a;            /* isaretli cikarma */
        uint16_t dogru = (uint16_t)(b - a);        /* isaretsiz, modulo 2^16 */

        printf("a=%04X b=%04X yanlis=%6d us dogru=%5u us\n", a, b, yanlis, dogru);
    }
    return 0;
}
